import json
with open('6ccf1748-b0d4-4c9c-aec3-e81ceb8532ab.jsonl') as f:
    for line in f:
        try:
            o=json.loads(line)
        except: continue
        t=o.get('type','')
        ts=o.get('timestamp','')
        msg=o.get('message',{})
        role=msg.get('role','') if isinstance(msg,dict) else ''
        content=msg.get('content','') if isinstance(msg,dict) else ''
        if isinstance(content,list):
            parts=[]
            for c in content:
                if isinstance(c,dict):
                    if c.get('type')=='text': parts.append(c['text'][:300])
                    elif c.get('type')=='tool_use': parts.append('[TOOL '+c.get('name','')+'] '+json.dumps(c.get('input',{}))[:200])
                    elif c.get('type')=='tool_result': parts.append('[RESULT] '+str(c.get('content',''))[:200])
            content=' | '.join(parts)
        print(f'{ts} {t}/{role}: {str(content)[:400]}')
        print('---')
"
